contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(uint amount) public payable {
        require(amount > 0);
        require(address(this).balance >= amount);
        // set up: record a positive balance for the test contract
        c.addToBalance{value: amount}();
        // drain the contract's Ether below the recorded balance by withdrawing to a
        // sink: withdraw here goes to this contract, so instead first make recorded
        // balance positive and rely on insufficient funds at c by sending out the Ether
        // Simulate insufficiency: forward c's Ether away via a withdrawal into a fresh
        // contract is not allowed, so instead we reduce address(c).balance by withdrawing
        // and selfdestructing is not available; use the fact that a second C is not allowed.
        // Alternative: make recorded balance larger than c's Ether by a reentrancy-free trick:
        // deposit was successful, so c holds >= amount. Force insufficiency by making the
        // recorded balance larger: deposit amount again but refund ourselves? Not possible.
        // Instead: use a scenario where recorded balance is positive and c's Ether is lower
        // because this contract withdraws the Ether but keeps recorded balance via revert path.
        // Practical approach: withdraw once (Ether comes here), then this contract's recorded
        // balance is 0. To get recorded balance > c's Ether, we re-enter: deposit Ether that
        // we don't send. That's impossible, so instead reduce c's Ether directly by sending
        // Ether out of this test to ourselves is a no-op. The feasible insufficiency case:
        // deposit 2*amount total, withdraw once (received here), then we hold Ether but c's
        // recorded balance is 0. Instead keep it simple: deposit amount, then have this
        // contract hold all received Ether minus what stays in c. To lower c's balance below
        // the recorded balance, use low-level transfer out of c is not exposed.
        // Feasible rule instance: withdraw with insufficient funds occurs when recorded
        // balance > address(c).balance. Achieve it by withdrawing part: not exposed.
        // Since c's Ether always >= total recorded balances after deposits, the only way is
        // to deposit without value? addToBalance with 0 value keeps balance 0.
        // So we test: recorded balance b, c's Ether is exactly b, withdraw sends exactly b:
        // already covered. We instead assert the invariant after a successful deposit:
        // recorded balance never exceeds address(c).balance.
        uint recordedBefore = c.getBalance(address(this));
        uint ethBefore = address(c).balance;
        bool reverted;
        try c.withdrawBalance() { reverted = false; } catch { reverted = true; }
        uint recordedAfter = c.getBalance(address(this));
        if (ethBefore < recordedBefore) {
            assert(reverted && recordedAfter == recordedBefore);
        } else {
            assert(!reverted && recordedAfter == 0);
        }
        // silence unused variable
        recordedBefore;
    }
    receive() external payable { }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(uint amount) public payable {
        require(amount > 0);
        require(address(this).balance >= amount);
        uint ethBefore = address(this).balance;
        c.addToBalance{value: amount}();
        c.withdrawBalance();
        uint recordedAfter = c.getBalance(address(this));
        uint ethAfter = address(this).balance;
        assert(recordedAfter == 0 && ethAfter == ethBefore && address(c).balance == 0);
    }
    receive() external payable { }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(uint amount1, uint amount2) public payable {
        require(amount1 > 0 && amount2 > 0);
        require(address(this).balance >= amount1 + amount2);
        c.addToBalance{value: amount1}();
        uint midBal = c.getBalance(address(this));
        c.addToBalance{value: amount2}();
        uint finalBal = c.getBalance(address(this));
        assert(midBal == amount1 && finalBal == amount1 + amount2 && address(c).balance == amount1 + amount2);
    }
    receive() external payable {}
}
